import pandas as pd, re, numpy as np
tr=pd.read_parquet('raw/gsm8k/main/train-00000-of-00001.parquet')
te=pd.read_parquet('raw/gsm8k/main/test-00000-of-00001.parquet')
def gt(a):
    return re.search(r"#### (\-?[0-9\.\,]+)", a).group(1).replace(',','')
def nums(q):
    return re.findall(r"\-?\d[\d,]*\.?\d*", q)
for name,df in [('train',tr),('test',te)]:
    qs=df['question']; ans=[gt(a) for a in df['answer']]
    qlen=qs.str.len()
    nnums=qs.apply(lambda q: len(nums(q)))
    numeric_ans=sum(1 for a in ans if re.fullmatch(r'\-?\d+',a))/len(ans)
    small=sum(1 for a in ans if re.fullmatch(r'\-?\d+',a) and abs(int(a))<=100)/len(ans)
    print(f'{name}: n={len(df)} qchars mean={qlen.mean():.0f} median={qlen.median():.0f} p90={qlen.quantile(.9):.0f} max={qlen.max()} | #nums mean={nnums.mean():.2f} | numeric_ans={numeric_ans:.3f} | answer<=100={small:.3f}')
    # last number in question equals answer
    last_eq=0; first_eq=0; max_eq=0
    for q,a in zip(qs,ans):
        ns=[x.replace(',','') for x in nums(q)]
        try: av=float(a)
        except: continue
        if ns:
            try:
                if float(ns[-1])==av: last_eq+=1
                if float(ns[0])==av: first_eq+=1
                if max(float(x) for x in ns)==av: max_eq+=1
            except: pass
    print(f'   last_num==ans {last_eq/len(df):.3f} first_num==ans {first_eq/len(df):.3f} max_num==ans {max_eq/len(df):.3f}')
